export function normalizePhone(input: string, defaultDial = "+966"): string {
  const trimmed = input.trim();
  const digits = trimmed.replace(/\D/g, "");
  if (!digits) return "";
  // Numbers entered through the app always carry their dial code (e.g.
  // "+966 50 123 4567") — keep the real country code intact.
  if (trimmed.startsWith("+")) return `+${digits}`;
  // Bare local number with no code → the admin's default country (Saudi
  // Arabia when unset), dropping any leading 0 (05X XXX XXXX → +9665XXXXXXXX).
  const dial = /^\+\d{1,4}$/.test(defaultDial) ? defaultDial : "+966";
  const local = digits.replace(/^0+/, "");
  if (local.length <= 9) return `${dial}${local}`;
  return `+${digits}`;
}

