// ---------- QR/UPI coin purchases (admin-verified) ----------
/** User submits a coin purchase paid via QR/UPI (with a screenshot). Creates a
 *  PENDING request — no coins are added until an admin approves it. */
export async function createCoinPurchase(input: {
  userId: string;
  packageId: string;
  screenshotUrl?: string;
  screenshotName?: string;
  paymentRef?: string;
  userIdNumber?: string;
}): Promise<{ ok: boolean; error?: string; request?: CoinPurchaseRequest }> {
  return withDB((db) => {
    const u = db.users.find((x) => x.id === input.userId);
    if (!u) return { ok: false as const, error: "User not found" };
    const cfg = db.config ?? defaultConfig();
    const pkg = (cfg.coinPackages ?? []).find((p) => p.id === input.packageId);
    if (!pkg) return { ok: false as const, error: "Unknown coin package" };
    if (pkg.active === false) return { ok: false as const, error: "This package is no longer available" };

    // Tax + service charge, from the SAME calculator the checkout screen used, so
    // the amount the admin verifies is exactly what the user was asked to pay.
    const bd = priceBreakdown(pkg.price, cfg.coinFees);

    const req: CoinPurchaseRequest = {
      id: `cpx_${crypto.randomUUID().slice(0, 8)}`,
      userId: u.id,
      userName: u.fullName,
      userIdNumber: (input.userIdNumber?.trim() || u.publicId || "").slice(0, 30),
      packageId: pkg.id,
      packageName: pkg.name,
      coins: pkg.coins,
      bonus: pkg.bonus ?? 0,
      // `price` stays the FULL amount the user actually paid, so every existing
      // report, export and total keeps working without change.
      price: bd.payable,
      basePrice: bd.base,
      tax: bd.tax,
      taxLabel: bd.taxLabel,
      serviceCharge: bd.service,
      serviceLabel: bd.serviceLabel,
      currency: cfg.paymentQr?.currency ?? "₹",
      screenshotUrl: input.screenshotUrl,
      screenshotName: input.screenshotName,
      paymentRef: input.paymentRef?.slice(0, 60),
      status: "pending",
      at: new Date().toISOString(),
    };
    if (!db.coinPurchases) db.coinPurchases = [];
    db.coinPurchases.unshift(req);
    db.coinPurchases = db.coinPurchases.slice(0, 5000);

    const time = new Date().toISOString();
    for (const a of db.users) {
      if (a.role !== "admin") continue;
      db.notifications.push({ id: `n_${crypto.randomUUID().slice(0, 8)}`, userId: a.id, type: "system", text: `💳 ${u.fullName} submitted a coin purchase: ${pkg.name} (${(pkg.coins + (pkg.bonus ?? 0)).toLocaleString()} coins for ${req.currency}${bd.payable}). Verify the payment.`, time, unread: true, cta: { label: "Review", href: "/admin/coin-purchases" } });
    }
    return { ok: true as const, request: req };
  });
}

/** Admin approves/rejects a coin purchase. Approve credits coins + bonus. */
export async function decideCoinPurchase(id: string, approve: boolean, adminName: string, note?: string): Promise<{ ok: boolean; error?: string }> {
  return withDB((db) => {
    const req = (db.coinPurchases ?? []).find((r) => r.id === id);
    if (!req) return { ok: false as const, error: "Purchase not found" };
    if (req.status !== "pending") return { ok: false as const, error: "This purchase was already decided" };
    const user = db.users.find((u) => u.id === req.userId);
    // Don't mark an APPROVE as done if we can't actually credit the buyer.
    if (approve && !user) return { ok: false as const, error: "That user no longer exists — cannot credit coins." };
    req.status = approve ? "approved" : "rejected";
    req.decidedAt = new Date().toISOString();
    req.decidedBy = adminName;
    if (note) req.note = note.slice(0, 200);

    const time = new Date().toISOString();
    if (approve && user) {
      const total = req.coins + (req.bonus ?? 0);
      user.coins = (user.coins ?? 0) + total;
      recordTx(db, { userId: user.id, userName: user.fullName, type: "purchase", coins: total, amount: req.price, status: "success", description: `Coin purchase approved: ${req.packageName}${req.bonus ? ` (+${req.bonus} bonus)` : ""}`, balanceAfter: user.coins });
      // COMPANY PROFIT from the coin sale → the "recharge" bucket of the Company
      // Profit ledger. We record the PAID coins (excluding any free bonus), so the
      // Admin Profit dashboard shows revenue from coin purchases as its own source.
      if (req.coins > 0) {
        recordCompanyProfit(db, { userId: user.id, userName: user.fullName, type: "recharge", coins: req.coins, ref: req.id, note: `Coin purchase: ${req.packageName} — ${req.currency ?? "SAR"} ${req.price}${req.bonus ? ` (+${req.bonus} bonus)` : ""}` });
      }
      // TRUST SHARE from recharge: when the economy + Trust Share are ON, a % of the
      // purchased coins is allocated to the Trust Fund (a company allocation from the
      // sale — it does NOT reduce the buyer's coins).
      const lz = db.config?.lotus;
      if (lz?.enabled && lz.trustEnabled !== false && req.coins > 0) {
        const tShare = Math.round(req.coins * Math.max(0, lz.trustSharePct ?? 5) / 100 * Math.max(0, lz.coinToLotus ?? 1) * 100) / 100;
        if (tShare > 0) {
          db.trustWallet = Math.round(((db.trustWallet ?? 0) + tShare) * 100) / 100;
          db.lotusGenerated = Math.round(((db.lotusGenerated ?? 0) + tShare) * 100) / 100;
          if (!db.trustWalletLog) db.trustWalletLog = [];
          db.trustWalletLog.unshift({ id: `tw_${crypto.randomUUID().slice(0, 10)}`, at: time, type: "credit", lotus: tShare, source: "recharge", userId: user.id, userName: user.fullName, note: `${lz.trustSharePct ?? 5}% of ${req.coins}-coin purchase (${req.packageName})` });
          db.trustWalletLog = db.trustWalletLog.slice(0, 50000);
        }
      }
      db.notifications.push({ id: `n_${crypto.randomUUID().slice(0, 8)}`, userId: user.id, type: "reward", text: `✅ Your coin purchase was approved — ${total.toLocaleString()} coins added to your wallet!`, time, unread: true, cta: { label: "Open wallet", href: "/wallet" } });
      awardXp(db, user, "purchase"); // supporting the app earns level XP

    } else if (!approve && user) {
      db.notifications.push({ id: `n_${crypto.randomUUID().slice(0, 8)}`, userId: user.id, type: "system", text: `❌ Your coin purchase (${req.packageName}) was not verified${note ? `: ${note}` : ""}. No coins were added — please contact support if you paid.`, time, unread: true, cta: { label: "Wallet", href: "/wallet" } });
    }
    return { ok: true as const };
  });
}

